1	<?php
2	
3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Billing\WebhookEvent;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Retail\CommissionPayout;
9	use App\Services\Stripe\CommissionVoidService;
10	use App\Services\Stripe\StripeConnectService;
11	use Illuminate\Http\JsonResponse;
12	use Illuminate\Http\Request;
13	use Illuminate\Support\Facades\DB;
14	use Illuminate\Support\Facades\Log;
15	use Stripe\Exception\SignatureVerificationException;
16	use Stripe\Webhook;
17	
18	// V2: Core. Processes Stripe Connect events: account updates, checkout completions, transfer status, payment intents. Drives the commission payout lifecycle.
19	class StripeConnectWebhookController extends Controller
20	{
21	    use ValidatesStripeWebhookPayload;
22	
23	    public function __invoke(Request $request): JsonResponse
24	    {
25	        $payload = $request->getContent();
26	        $sigHeader = $request->header('Stripe-Signature');
27	
28	        if (! $sigHeader) {
29	            return response()->json(['error' => 'Missing signature'], 400);
30	        }
31	
32	        // Try both Connect and platform webhook secrets so one endpoint URL
33	        // can handle events from connected accounts and destination charges.
34	        $secrets = array_filter([
35	            config('services.stripe.connect_webhook_secret'),
36	            config('services.stripe.webhook_secret'),
37	        ]);
38	
39	        if ($secrets === []) {
40	            return response()->json(['error' => 'No webhook secret configured'], 400);
41	        }
42	
43	        $event = null;
44	        foreach ($secrets as $secret) {
45	            try {
46	                $event = Webhook::constructEvent($payload, $sigHeader, $secret);
47	                break;
48	            } catch (SignatureVerificationException) {
49	                continue;
50	            } catch (\Exception $e) {
51	                Log::warning('Stripe webhook parse error', ['error' => $e->getMessage()]);
52	
53	                return response()->json(['error' => 'Invalid payload'], 400);
54	            }
55	        }
56	
57	        if (! $event) {
58	            Log::warning('Stripe webhook signature verification failed for all configured secrets');
59	
60	            return response()->json(['error' => 'Invalid signature'], 400);
61	        }
62	
63	        if (! $this->validateEventStructure($event)) {
64	            return response()->json(['error' => 'Invalid payload structure'], 400);
65	        }
66	
67	        // Idempotency: firstOrCreate on the UNIQUE stripe_event_id. wasRecentlyCreated
68	        // distinguishes "won the race / first delivery" from "duplicate — skip".
69	        // Stripe event IDs are globally unique across platform + Connect events,
70	        // so billing.webhook_events covers both this controller and StripeWebhookController.
71	        // The row is committed before the match() dispatch: if a handler throws a 500,
72	        // Stripe's retry will find the existing row here and skip re-triggering the crash.
73	        $webhookEvent = WebhookEvent::firstOrCreate(
74	            ['stripe_event_id' => $event->id],
75	            ['event_type' => $event->type, 'processed_at' => now()]
76	        );
77	
78	        if (! $webhookEvent->wasRecentlyCreated) {
79	            return response()->json(['received' => true]);
80	        }
81	
82	        // Payload is HMAC-verified; set via forceFill (not mass-assignment) to preserve $fillable restriction.
83	        $webhookEvent->forceFill(['payload' => json_decode($payload, true)])->save();
84	
85	        return $this->handleParsedEvent($event);
86	    }
87	
88	    /**
89	     * Dispatch a verified, de-duplicated Stripe Event to the appropriate handler.
90	     * Extracted from __invoke() so it can be unit-tested without HMAC signing.
91	     *
92	     * Guards account-scoped event types by verifying the HMAC-signed top-level
93	     * `event->account` field matches `data.object->id`. A mismatch means the
94	     * payload was tampered with; we reject with 400 rather than mutating records.
95	     */
96	    public function handleParsedEvent(\Stripe\Event $event): JsonResponse
97	    {
98	        // For account-scoped events, event->account is the HMAC-signed source of truth.
99	        // If data.object.id differs, reject — payload could have been tampered with
100	        // to mutate a victim account using the attacker's valid HMAC.
101	        //
102	        // account.application.* events are excluded: their data.object is an Application
103	        // (id = ca_xxx), not an Account, so the id won't match event->account by design.
104	        $accountScopedPrefixes = ['account.', 'capability.'];
105	        $isAccountScoped = collect($accountScopedPrefixes)
106	            ->contains(fn ($p) => str_starts_with($event->type, $p));
107	
108	        if ($isAccountScoped && ! str_starts_with($event->type, 'account.application.')) {
109	            $topLevelAccount = $event->account ?? null;
110	            $objectId = $event->data->object->id ?? null;
111	
112	            if ($topLevelAccount === null || $topLevelAccount !== $objectId) {
113	                Log::warning('stripe.connect.account_mismatch', [
114	                    'event_id' => $event->id,
115	                    'event_account' => $topLevelAccount,
116	                    'object_id' => $objectId,
117	                ]);
118	
119	                return response()->json(['error' => 'account_mismatch'], 400);
120	            }
121	        }
122	
123	        match ($event->type) {
124	            'account.updated' => $this->handleAccountUpdated($event->data->object),
125	            'account.application.deauthorized' => $this->handleAccountDeauthorized((string) ($event->account ?? '')),
126	            'checkout.session.completed' => $this->handleCheckoutSessionCompleted($event->data->object, (string) ($event->account ?? '')),
127	            'transfer.created' => $this->handleTransferCreated($event->data->object),
128	            'transfer.failed' => $this->handleTransferFailed($event->data->object),
129	            'transfer.reversed' => $this->handleTransferReversed($event->data->object),
130	            'payment_intent.succeeded' => $this->handlePaymentIntentSucceeded($event->data->object, (string) ($event->account ?? '')),
131	            'payment_intent.payment_failed' => $this->handlePaymentIntentFailed($event->data->object),
132	            default => Log::debug('Unhandled Stripe Connect event', ['type' => $event->type]),
133	        };
134	
135	        return response()->json(['received' => true]);
136	    }
137	
138	    private function handleCheckoutSessionCompleted(object $checkoutSession, string $connectedAccountId): void
139	    {
140	        Log::debug('Stripe checkout session completed (no-op in V2)', [
141	            'checkout_session_id' => $checkoutSession->id ?? null,
142	            'connected_account_id' => $connectedAccountId,
143	        ]);
144	    }
145	
146	    /**
147	     * Handle account.application.deauthorized — fired when an Express account owner
148	     * revokes access via their Stripe dashboard. Mark them disconnected locally so
149	     * the payout job stops targeting their account and the UI surfaces the disconnect.
150	     *
151	     * Note: event->account is the connected account ID (HMAC-signed); event->data->object
152	     * is an Application object whose id will differ. The account-scope guard is skipped
153	     * for account.application.* events for this reason.
154	     */
155	    private function handleAccountDeauthorized(string $stripeAccountId): void
156	    {
157	        if (! $stripeAccountId) {
158	            Log::warning('stripe.connect.deauthorize_missing_account');
159	
160	            return;
161	        }
162	
163	        $professional = Professional::where('stripe_connect_account_id', $stripeAccountId)->first();
164	
165	        if (! $professional) {
166	            Log::debug('Stripe account.application.deauthorized for unknown account', ['account_id' => $stripeAccountId]);
167	
168	            return;
169	        }
170	
171	        $professional->update(['stripe_connect_status' => 'disconnected']);
172	
173	        Log::info('Stripe Connect account deauthorized via dashboard', [
174	            'professional_id' => $professional->id,
175	            'account_id' => $stripeAccountId,
176	        ]);
177	    }
178	
179	    private function handleAccountUpdated(object $account): void
180	    {
181	        // Bust the /stripe/status cache for this account regardless of whether
182	        // the local stripe_connect_status enum changes — fields like charges_enabled,
183	        // payouts_enabled, and requirements can flip without affecting the
184	        // collapsed status string, and the dashboard surfaces those directly.
185	        // Done before the unknown-account / disconnected guards so a stale
186	        // entry can never outlive a legitimate Stripe-side change.
187	        StripeConnectService::forgetStatusCache((string) $account->id);
188	
189	        $professional = Professional::where('stripe_connect_account_id', $account->id)->first();
190	
191	        if (! $professional) {
192	            Log::debug('Stripe account.updated for unknown account', ['account_id' => $account->id]);
193	
194	            return;
195	        }
196	
197	        // Respect local disconnect: if the professional has soft-disconnected
198	        // the account, ignore incoming Stripe events until they explicitly
199	        // reconnect via createOnboardingLink. Prevents a late account.updated
200	        // event from silently re-activating a disconnected account.
201	        if ($professional->stripe_connect_status === 'disconnected') {
202	            Log::debug('Stripe account.updated skipped — account locally disconnected', [
203	                'professional_id' => $professional->id,
204	                'account_id' => $account->id,
205	            ]);
206	
207	            return;
208	        }
209	
210	        $status = StripeConnectService::determineAccountStatus($account);
211	
212	        if ($professional->stripe_connect_status !== $status) {
213	            $oldStatus = $professional->stripe_connect_status;
214	
215	            // Atomic: if flushHeldCommissions throws, the status update is rolled back.
216	            // The professional stays in their prior state; the next account.updated
217	            // (new event_id, bypasses idempotency) retries the full transition cleanly.
218	            DB::transaction(function () use ($professional, $status, $oldStatus) {
219	                $professional->update(['stripe_connect_status' => $status]);
220	
221	                // When an affiliate transitions to 'active', flush any held commissions
222	                // so they enter the normal payout pipeline immediately.
223	                if ($status === 'active' && $oldStatus !== 'active') {
224	                    app(CommissionVoidService::class)->flushHeldCommissions($professional);
225	                }
226	            });
227	
228	            Log::info('Stripe Connect status updated', [
229	                'professional_id' => $professional->id,
230	                'old_status' => $oldStatus,
231	                'new_status' => $status,
232	            ]);
233	        }
234	    }
235	
236	    private function handleTransferCreated(object $transfer): void
237	    {
238	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
239	
240	        if (! $payoutId) {
241	            return;
242	        }
243	
244	        Log::info('Stripe transfer created', [
245	            'transfer_id' => $transfer->id,
246	            'payout_id' => $payoutId,
247	        ]);
248	    }
249	
250	    private function handleTransferFailed(object $transfer): void
251	    {
252	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
253	
254	        if (! $payoutId) {
255	            return;
256	        }
257	
258	        $payout = CommissionPayout::find($payoutId);
259	        if ($payout && ! in_array($payout->status, ['failed', 'completed', 'cancelled'], true)) {
260	            $payout->forceFill([
261	                'status' => 'failed',
262	                'failure_code' => 'transfer_failed_webhook',
263	                'failure_reason' => 'Transfer failed according to Stripe webhook',
264	            ])->save();
265	        }
266	
267	        Log::warning('Stripe transfer failed', [
268	            'transfer_id' => $transfer->id,
269	            'payout_id' => $payoutId,
270	        ]);
271	    }
272	
273	    /**
274	     * Handle transfer.reversed — funds reached the affiliate and were subsequently
275	     * clawed back by Stripe (compliance hold, account closure, etc.).
276	     *
277	     * Unlike transfer.failed (funds never left), a reversal can arrive after the payout
278	     * is already 'completed'. The brand was charged; the affiliate's Stripe balance was
279	     * drained. The only safe action is to mark the payout 'reversed', flag it for manual
280	     * recovery, and surface it to ops — no auto-refund attempt here.
281	     */
282	    private function handleTransferReversed(object $transfer): void
283	    {
284	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
285	
286	        if (! $payoutId) {
287	            return;
288	        }
289	
290	        $payout = CommissionPayout::find($payoutId);
291	
292	        if (! $payout) {
293	            Log::warning('stripe.transfer_reversed.payout_not_found', [
294	                'transfer_id' => $transfer->id,
295	                'payout_id' => $payoutId,
296	            ]);
297	
298	            return;
299	        }
300	
301	        // Idempotent: a duplicate webhook for an already-reversed payout is a no-op.
302	        if ($payout->status === 'reversed') {
303	            return;
304	        }
305	
306	        $previousStatus = $payout->status;
307	
308	        // transfer.reversed can arrive after 'completed' — this is the most common
309	        // real-world scenario (transfer confirmed → payout marked complete → Stripe later
310	        // reverses). Completed payouts must be updatable here, unlike handleTransferFailed.
311	        $payout->forceFill([
312	            'status' => 'reversed',
313	            'failure_code' => 'transfer_reversed',
314	            'failure_reason' => 'Transfer reversed by Stripe after delivery — funds clawed back',
315	            'needs_manual_refund' => true,
316	        ])->save();
317	
318	        Log::warning('stripe.transfer_reversed', [
319	            'transfer_id' => $transfer->id,
320	            'payout_id' => $payoutId,
321	            'previous_status' => $previousStatus,
322	        ]);
323	    }
