325	    private function handlePaymentIntentSucceeded(object $paymentIntent, string $connectedAccountId = ''): void
326	    {
327	        // Commission payout payment intent
328	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
329	        if (! $payoutId) {
330	            return;
331	        }
332	
333	        Log::info('Stripe payment intent succeeded for payout', [
334	            'payment_intent_id' => $paymentIntent->id,
335	            'payout_id' => $payoutId,
336	        ]);
337	    }
