339	    private function handlePaymentIntentFailed(object $paymentIntent): void
340	    {
341	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
342	
343	        if (! $payoutId) {
344	            return;
345	        }
346	
347	        $payout = CommissionPayout::find($payoutId);
348	        if ($payout && ! in_array($payout->status, ['failed', 'completed'])) {
349	            $payout->forceFill([
350	                'status' => 'failed',
351	                'failure_code' => 'payment_failed_webhook',
352	                'failure_reason' => $paymentIntent->last_payment_error?->message ?? 'Payment failed',
353	            ])->save();
354	        }
355	
356	        Log::warning('Stripe payment intent failed for payout', [
357	            'payment_intent_id' => $paymentIntent->id,
358	            'payout_id' => $payoutId,
359	        ]);
360	    }
