15	/**
16	 * Handles voiding commissions for affiliates who haven't connected Stripe.
17	 *
18	 * Phase 4+ model: a "pending commission" is a commerce.orders row with
19	 * status='approved' AND payout_id IS NULL. Voiding it sets status='voided';
20	 * the rollup_apply_delta trigger automatically reverses the rollup deltas.
21	 * The audit trail goes into commerce.order_events with event_type='voided'.
22	 *
23	 * Two phases run on the daily cron:
24	 *   1. processVoidableCommissions() — void orders past their 30-day window
25	 *   2. sendGracePeriodWarnings()    — nudge affiliates to connect Stripe
26	 *
27	 * Called from ProcessCommissionPayoutsJob after normal payout processing.
28	 */
29	class CommissionVoidService
30	{
31	    private int $voidWindowDays;
32	
33	    private int $gracePeriodDays;
34	
35	    public function __construct(private readonly NotificationPublisher $publisher)
36	    {
37	        $this->voidWindowDays = (int) config('partna.store.commission_void_window_days', 30);
38	        $this->gracePeriodDays = (int) config('partna.store.grace_period_days', 30);
39	    }
40	
41	    /**
42	     * Find and void all approved orders past their void window
43	     * for affiliates without active Stripe Connect accounts.
44	     *
45	     * @return array{voided_count: int, voided_cents: int}
46	     */
47	    public function processVoidableCommissions(): array
48	    {
49	        $cutoff = now()->utc()->subDays($this->voidWindowDays);
50	        $stats = ['voided_count' => 0, 'voided_cents' => 0];
51	
52	        // Pre-fetch inactive affiliate IDs so the orders query uses set membership
53	        // (hash join) instead of a correlated EXISTS probe per row.
54	        $inactiveAffiliateIds = Professional::query()
55	            ->where('stripe_connect_status', '!=', 'active')
56	            ->pluck('id')
57	            ->all();
58	
59	        if ($inactiveAffiliateIds === []) {
60	            return $stats;
61	        }
62	
63	        // Chunk to avoid OOM. Each order is voided with an optimistic update so a
64	        // concurrent payout-stamp won't get overwritten.
65	        Order::query()
66	            ->where('status', 'approved')
67	            ->whereNull('payout_id')
68	            ->where('occurred_at', '<=', $cutoff)
69	            ->whereIn('affiliate_professional_id', $inactiveAffiliateIds)
70	            ->chunkById(500, function ($orders) use (&$stats) {
71	                foreach ($orders as $order) {
72	                    try {
73	                        if ($this->voidOrder($order, 'no_stripe_connected')) {
74	                            $stats['voided_count']++;
75	                            $stats['voided_cents'] += (int) $order->commission_cents;
76	                        }
77	                    } catch (\Throwable $e) {
78	                        Log::error('Failed to void commission order', [
79	                            'order_id' => (string) $order->id,
80	                            'error' => $e->getMessage(),
81	                        ]);
82	                    }
83	                }
84	            });
85	
86	        if ($stats['voided_count'] > 0) {
87	            Log::info('Commission void processing complete', $stats);
88	        }
89	
90	        return $stats;
91	    }
92	
93	    /**
94	     * Void a single approved order. Uses an optimistic lock guarded by
95	     * status='approved' so a concurrent terminal-state transition (refund/cancel)
96	     * can't be overwritten.
97	     *
98	     * Two payout-id contexts:
99	     *   - $expectedPayoutId === null (default): the order must be unclaimed
100	     *     (payout_id IS NULL). Used by the 30-day-window void and by
101	     *     staff/disconnect manual voids — voiding can't proceed once a
102	     *     payout batch has stamped the row.
103	     *   - $expectedPayoutId set: the order must be linked to that exact
104	     *     (just-cancelled) payout. Used by cancelExpiredPayout when the
105	     *     affiliate didn't activate Stripe Connect within the grace window.
106	     *
107	     * Setting status='voided' fires the rollup_apply_delta trigger which subtracts
108	     * the order's contribution from brand_affiliate_rollup and adds the full
109	     * commission_cents to reversed_commission_cents.
110	     *
111	     * @return bool True if the order was voided, false if it was already claimed.
112	     */
113	    public function voidOrder(Order $order, string $reason, ?string $expectedPayoutId = null): bool
114	    {
115	        return DB::transaction(function () use ($order, $reason, $expectedPayoutId): bool {
116	            $query = Order::query()
117	                ->where('id', $order->id)
118	                ->where('status', 'approved');
119	
120	            if ($expectedPayoutId === null) {
121	                $query->whereNull('payout_id');
122	            } else {
123	                $query->where('payout_id', $expectedPayoutId);
124	            }
125	
126	            $updated = $query->update(['status' => 'voided']);
127	
128	            if ($updated === 0) {
129	                Log::info('Skipped voiding order — status or payout_id changed concurrently', [
130	                    'order_id' => (string) $order->id,
131	                    'expected_payout_id' => $expectedPayoutId,
132	                ]);
133	
134	                return false;
135	            }
136	
137	            // OrderEvent::$guarded = ['*'] — go through forceFill to insert.
138	            (new OrderEvent)->forceFill([
139	                'order_id' => $order->id,
140	                'event_type' => 'voided',
141	                'source' => str_starts_with($reason, 'staff_manual') ? 'manual' : 'system',
142	                'shopify_event_id' => null,
143	                'shopify_triggered_at' => now(),
144	                'amount_delta_cents' => -1 * (int) $order->commission_cents,
145	                'metadata' => [
146	                    'reason' => $reason,
147	                    'voided_at' => now()->toIso8601String(),
148	                ],
149	            ])->save();
150	
151	            return true;
152	        });
153	    }
