155	    /**
156	     * Cancel commission payouts whose 60-day grace window has expired
157	     * without the affiliate connecting Stripe Connect.
158	     *
159	     * Scans pending/pending_funds payouts past their void_at via the
160	     * partial index commission_payouts_void_at_idx, then for each one
161	     * checks the affiliate's Stripe status and cancels if not active.
162	     * Linked orders are voided in the same transaction so the affiliate's
163	     * dashboard shows a consistent "expired" state.
164	     *
165	     * Called from VoidExpiredPayoutsJob (nightly cron).
166	     *
167	     * @return array{cancelled_count: int, cancelled_cents: int, voided_entries: int}
168	     */
169	    public function processExpiredPayouts(): array
170	    {
171	        $stats = ['cancelled_count' => 0, 'cancelled_cents' => 0, 'voided_entries' => 0];
172	
173	        // Pre-fetch inactive affiliate IDs so the main query uses set membership
174	        // (hash join) instead of a correlated per-row EXISTS probe against professionals.
175	        $inactiveAffiliateIds = Professional::query()
176	            ->where('stripe_connect_status', '!=', 'active')
177	            ->pluck('id')
178	            ->all();
179	
180	        if ($inactiveAffiliateIds === []) {
181	            return $stats;
182	        }
183	
184	        CommissionPayout::query()
185	            ->whereIn('status', ['pending', 'pending_funds'])
186	            ->where('void_at', '<', now())
187	            ->whereIn('affiliate_professional_id', $inactiveAffiliateIds)
188	            ->with('brandProfessional:id,display_name')
189	            ->chunkById(200, function ($payouts) use (&$stats): void {
190	                foreach ($payouts as $payout) {
191	                    try {
192	                        $this->cancelExpiredPayout($payout, $stats);
193	                    } catch (\Throwable $e) {
194	                        Log::error('Failed to cancel expired payout', [
195	                            'payout_id' => $payout->id,
196	                            'exception' => $e,
197	                        ]);
198	                    }
199	                }
200	            });
201	
202	        return $stats;
203	    }
