205	    /**
206	     * Cancel a single expired payout and void its linked orders.
207	     * Optimistic lock guards against an in-flight ExecuteCommissionPayoutJob
208	     * advancing the status to 'collecting' between the SELECT and UPDATE.
209	     */
210	    private function cancelExpiredPayout(CommissionPayout $payout, array &$stats): void
211	    {
212	        $cancelled = false;
213	
214	        DB::transaction(function () use ($payout, &$stats, &$cancelled): void {
215	            $updated = CommissionPayout::query()
216	                ->where('id', $payout->id)
217	                ->whereIn('status', ['pending', 'pending_funds'])
218	                ->update([
219	                    'status' => 'cancelled',
220	                    'failure_code' => 'grace_period_expired',
221	                    'failure_reason' => 'Affiliate did not connect Stripe Connect within the grace period.',
222	                    'updated_at' => now(),
223	                ]);
224	
225	            if ($updated === 0) {
226	                Log::info('Skipped cancelling expired payout — status changed concurrently', [
227	                    'payout_id' => $payout->id,
228	                ]);
229	
230	                return;
231	            }
232	
233	            // Phase 4+: void the linked orders directly. The rollup trigger handles
234	            // the per-day delta reversal automatically. We do this BEFORE clearing
235	            // payout_id so the optimistic guard (status='approved' AND payout_id=?)
236	            // catches concurrent payout-stamp races.
237	            $voidedOrders = $this->voidOrdersLinkedToPayout($payout->id, 'payout_grace_expired');
238	
239	            // Now clear the payout_id stamp on those (now voided) orders so the
240	            // legacy join-based reports don't surface them as still linked.
241	            $this->clearOrderStampsForVoidedPayout($payout->id);
242	
243	            $stats['cancelled_count']++;
244	            $stats['cancelled_cents'] += (int) $payout->gross_commission_cents;
245	            $stats['voided_entries'] += $voidedOrders;
246	            $cancelled = true;
247	        });
248	
249	        if ($cancelled) {
250	            $this->publisher->publish(
251	                professionalId: $payout->affiliate_professional_id,
252	                frontendType: 'Warning',
253	                category: 'commissions',
254	                title: 'Commission payout expired',
255	                body: sprintf(
256	                    'Your %s payout from %s has been cancelled because Stripe Connect was not activated within the grace period.',
257	                    Money::format($payout->net_payout_cents, $payout->currency_code),
258	                    $payout->brandProfessional?->display_name ?? 'a brand',
259	                ),
260	                dedupeKey: "payout_voided.{$payout->id}",
261	                ctaUrl: '/account/settings?section=stripe',
262	                retentionConfigKey: 'commission',
263	            );
264	        }
265	    }
