498	    /**
499	     * Voids up to $cap pending orders for a specific affiliate-brand pair.
500	     * Returns overflow: true (without voiding) when count exceeds cap — caller should
501	     * dispatch VoidPendingCommissionsForLinkJob instead.
502	     *
503	     * @return array{count: int, total_cents: int, overflow: bool}
504	     */
505	    public function voidPendingForAffiliateBrand(
506	        string $affiliateProfessionalId,
507	        string $brandProfessionalId,
508	        string $reason,
509	        int $cap = 200,
510	    ): array {
511	        $pendingCount = Order::query()
512	            ->where('affiliate_professional_id', $affiliateProfessionalId)
513	            ->where('brand_professional_id', $brandProfessionalId)
514	            ->where('status', 'approved')
515	            ->whereNull('payout_id')
516	            ->count();
517	
518	        if ($pendingCount > $cap) {
519	            return ['count' => 0, 'total_cents' => 0, 'overflow' => true];
520	        }
521	
522	        return $this->runVoidLoop($affiliateProfessionalId, $brandProfessionalId, $reason);
523	    }
