525	    /**
526	     * Loops voidOrder() over every approved+unstamped order for the pair.
527	     *
528	     * @return array{count: int, total_cents: int, overflow: bool}
529	     */
530	    public function runVoidLoop(
531	        string $affiliateProfessionalId,
532	        string $brandProfessionalId,
533	        string $reason,
534	    ): array {
535	        $voidedCount = 0;
536	        $voidedCents = 0;
537	
538	        Order::query()
539	            ->where('affiliate_professional_id', $affiliateProfessionalId)
540	            ->where('brand_professional_id', $brandProfessionalId)
541	            ->where('status', 'approved')
542	            ->whereNull('payout_id')
543	            ->orderBy('occurred_at')
544	            ->chunkById(50, function ($orders) use (&$voidedCount, &$voidedCents, $reason): void {
545	                foreach ($orders as $order) {
546	                    if ($this->voidOrder($order, $reason)) {
547	                        $voidedCount++;
548	                        $voidedCents += (int) $order->commission_cents;
